attribute vec3 aA, aB; attribute float aT, aK; uniform float uTime; varying float vS, vY, vU, vK, vL;
    void main(){
      float u = uTime - aT - 0.10; if (u < 0. || u > 0.95){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = position.x*.5 + .5, W = .16;
      vec3 d = aB - aA, t = normalize(d);
      vec3 P = aA + d*s + vec3(0., -.1*4.*s*(1. - s), 0.);       // minimal sag
      vec3 side = normalize(cross(t, P - cameraPosition));
      vS = s; vY = position.y*W; vU = u; vK = aK; vL = length(d);
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*W, 1.);
    }

