    float fbm(vec2 p){ return .55*vn(p) + .3*vn(p*2.1 + 3.7) + .15*vn(p*4.3 + 7.1); }
    void main(){
      float s = vS, u = vU, M = 0.09;
      vec3 col = mix(uCW, uCT, vK);
      float g = (1. - pow(1. - clamp(u/M, 0., 1.), 2.))*.5;       // forms from both ends and meets in the middle
      float grown = max(smoothstep(g + .04, g - .06, s), smoothstep(1. - g - .04, 1. - g + .06, s));
      float wipe = max(u - .55, 0.)/.3;                           // clears from the Fighter's end; the target end goes last
      float alive = grown*smoothstep(wipe - .1, wipe + .25, s);
      // smoke drifts fast along the line: toward the target (Pressure) or back toward the Tank (Provoke)
      float dir = vK < .5 ? 1. : -1., x = s*vL;
      float n  = fbm(vec2(x*2.2 - dir*u*9., vY*14. + u*1.5));
      float n2 = fbm(vec2(x*5.  - dir*u*14., vY*26. - u*2.));
      float prof = pow(sin(3.14159*s), .5);
      // three loose wisps, each wandering and breaking up on its own — no band, no fixed centre
      float dens = 0.;
      for (int i=0;i<3;i++){
        float fi = float(i);
        float yy = vY - (fi - 1.)*.042*prof + (fbm(vec2(x*1.1 - dir*u*6. + fi*5.3, fi*2.7)) - .5)*.08;
        float w = (.009 + .016*prof)*(.7 + .6*fbm(vec2(x*2. - dir*u*8. + fi*3.1, fi + 1.)));
        float brk = smoothstep(.3, .75, fbm(vec2(x*2.4 - dir*u*12. + fi*7.7, fi*4.3 + 2.)));
        dens += exp(-pow(abs(yy)/w, 1.6))*brk*(.5 + .5*n2);
      }
      dens *= prof*.55;
