      float r = u - M, puff = 0.;
      if (r > 0.){
        if (vK < .5){ for (int i=0;i<3;i++){ float h = (r - float(i)*.06)*3.6; puff += exp(-pow((s - h)/.08, 2.))*step(0., h)*step(h, 1.08); } }
